// ============================================
// Homepage: shows the projects you marked
// star: true (maximum 3). Empty slots show
// "Coming soon".
// You do not edit this file.
// ============================================

const cardsBox = document.getElementById("cards");

if (cardsBox) {
  const groups = [
    { key: "automation",     name: "Automation",     list: typeof automationProjects !== "undefined" ? automationProjects : [] },
    { key: "data-analytics", name: "Data Analytics", list: typeof analyticsProjects  !== "undefined" ? analyticsProjects  : [] },
    { key: "websites",       name: "Website",        list: typeof websiteProjects    !== "undefined" ? websiteProjects    : [] }
  ];

  // Collect every starred project
  const starred = [];
  groups.forEach(function (g) {
    g.list.forEach(function (p) {
      if (p.star) {
        starred.push({ group: g, project: p });
      }
    });
  });

  const MAX = 3;

  // Starred projects (each opens its place on the Work page)
  starred.slice(0, MAX).forEach(function (item) {
    const p = item.project;

    const card = document.createElement("a");
    card.className = "card card-live";
    card.href = "work.html#" + item.group.key + (p.id ? "/" + p.id : "");

    const tag = document.createElement("span");
    tag.className = "tag";
    tag.textContent = item.group.name;

    const body = document.createElement("div");
    body.className = "card-body";

    const title = document.createElement("h3");
    title.textContent = p.title;

    const text = document.createElement("p");
    text.textContent = p.summary;

    body.append(title, text);

    const more = document.createElement("span");
    more.className = "card-link";
    more.textContent = "View project →";

    card.append(tag, body, more);
    cardsBox.append(card);
  });

  // Fill the empty slots
  for (let i = starred.length; i < MAX; i++) {
    const card = document.createElement("a");
    card.className = "card card-soon";
    card.href = "work.html";

    const tag = document.createElement("span");
    tag.className = "tag";
    tag.textContent = "Project";

    const body = document.createElement("div");
    body.className = "card-body";

    const title = document.createElement("h3");
    title.textContent = "Coming soon";

    const text = document.createElement("p");
    text.textContent = "A new project is on the way.";

    body.append(title, text);
    card.append(tag, body);
    cardsBox.append(card);
  }
}